243	/**
244	 * Initialize Socket.IO components
245	 * Must be called after HTTP server is created
246	 * @param {http.Server} httpServer - HTTP server instance
247	 * @returns {SocketManager} Socket manager instance
248	 */
249	function initializeSocketIO(httpServer) {
250	  container.register('socketManager', (c) => {
251	    const manager = new SocketManager(
252	      httpServer,
253	      c.resolve('tokenService'),
254	      c.resolve('authorizationService'),
255	      c.resolve('config'),
256	      c.resolve('logger'),
257	      c.resolve('metricsCollector')
258	    );
259	    
260	    // Initialize the Socket.IO server
261	    manager.initialize();
262	    
263	    return manager;
264	  }, 'singleton');
265	
266	  const socketManager = container.resolve('socketManager');
267	
268	  // Provide lazy socket manager access to services that need it (LOW-14)
269	  // Instead of mutating `.socketManager` after resolution, we set a lazy getter
270	  // that resolves from the DI container on first access.
271	  const servicesNeedingSocket = [
272	    'scoringService',
273	    'competitionService',
274	    'teamService',
275	    'judgeService',
276	    'adminService',
277	  ];
278	
279	  for (const serviceName of servicesNeedingSocket) {
280	    const service = container.resolve(serviceName);
281	    Object.defineProperty(service, 'socketManager', {
282	      get() {
283	        // Replace the getter with the resolved value after first access
284	        const sm = container.resolve('socketManager');
285	        Object.defineProperty(this, 'socketManager', { value: sm, writable: true, configurable: true });
286	        return sm;
287	      },
288	      configurable: true,
289	    });
290	  }
291	
292	  // Register event handlers
293	  container.register('scoringHandler', (c) => {
294	    const handler = new ScoringHandler(
295	      c.resolve('socketManager'),
296	      c.resolve('scoringService'),
297	      c.resolve('authorizationService'),
298	      c.resolve('logger'),
299	      c.resolve('judgeService')
300	    );
301	    
302	    // Register event handlers
303	    handler.register();
304	    
305	    return handler;
306	  }, 'singleton');
307	
308	  container.register('notificationHandler', (c) => {
309	    const handler = new NotificationHandler(
310	      c.resolve('socketManager'),
311	      c.resolve('logger')
312	    );
313	    
314	    // Register event handlers
315	    handler.register();
316	    
317	    return handler;
318	  }, 'singleton');
319	
320	  // Resolve handlers to initialize
321	  container.resolve('scoringHandler');
322	  container.resolve('notificationHandler');
323	
324	  return socketManager;
325	}
326	
327	/**
328	 * Warm cache with frequently accessed data
329	 * Should be called after application initialization
330	 * @returns {Promise<Object>} Warming statistics
331	 */
332	async function warmCache() {
333	  try {
334	    const cacheWarmer = container.resolve('cacheWarmer');
335	    const stats = await cacheWarmer.warmCache();
336	    return stats;
337	  } catch (error) {
338	    const logger = container.resolve('logger');
339	    logger.error('Cache warming failed during startup', { error: error.message });
340	    // Don't throw - cache warming failure shouldn't prevent app startup
341	    return { errors: [{ type: 'startup', error: error.message }] };
342	  }
343	}
344	
345	module.exports = { bootstrap, initializeSocketIO, warmCache };
