1	/**
2	 * Route Loader Module
3	 * 
4	 * Centralizes route registration and applies middleware in the correct order:
5	 * security → logging → parsing → authentication → routes → error handling
6	 * 
7	 * Routes are organized by domain and loaded from the DI container
8	 * 
9	 * Requirements: 14.1, 14.2, 14.3, 14.7
10	 * 
11	 * @module routes/index
12	 */
13	
14	const express = require('express');
15	const createHealthRoutes = require('./health.routes');
16	const createAuthRoutes = require('./auth.routes');
17	const createPlayerRoutes = require('./player.routes');
18	const createCoachRoutes = require('./coach.routes');
19	const createAdminRoutes = require('./admin.routes');
20	const createCompetitionRoutes = require('./competition.routes');
21	const createTeamRoutes = require('./team.routes');
22	const createScoringRoutes = require('./scoring.routes');
23	const createJudgeRoutes = require('./judge.routes');
24	const createSuperAdminRoutes = require('./super-admin.routes');
25	const createPaymentRoutes = require('./payment.routes');
26	const createPublicRoutes = require('./public.routes');
27	
28	// CSRF token endpoint
29	const { csrfTokenHandler } = require('../middleware/csrf.middleware');
30	
31	/**
32	 * Load and register all application routes
33	 * 
34	 * Routes are grouped by domain with appropriate prefixes:
35	 * - /api/health - Health check and metrics endpoints
36	 * - /api/auth - Authentication and authorization
37	 * - /api/players - Player management
38	 * - /api/coaches - Coach management
39	 * - /api/admin - Admin management
40	 * - /api/competitions - Competition management
41	 * - /api/teams - Team management
42	 * - /api/scoring - Scoring operations
43	 * 
44	 * Middleware is applied in the correct order for each route group
45	 * 
46	 * @param {express.Application} app - Express application instance
47	 * @param {Object} options - Configuration options
48	 * @param {Function} options.authLimiter - Rate limiter for authentication endpoints
49	 * @returns {void}
50	 */
51	function loadRoutes(app, container, options = {}) {
52	  const { authLimiter } = options;
53	
54	  // ============================================================
55	  // HEALTH CHECK ROUTES (no authentication required)
56	  // ============================================================
57	  // These should be registered first for quick access by load balancers
58	  const healthRouter = createHealthRoutes(container);
59	  app.use('/api/health', healthRouter);
60	
61	  // ============================================================
62	  // CSRF TOKEN ENDPOINT (Requirement 17.3)
63	  // ============================================================
64	  // Clients that use cookie-based sessions can fetch a CSRF token here.
65	  // Bearer-token (JWT) clients are automatically exempt from CSRF checks.
66	  app.get('/api/csrf-token', csrfTokenHandler);
67	
68	  // ============================================================
69	  // AUTHENTICATION ROUTES (with rate limiting)
70	  // ============================================================
71	  // Apply rate limiting to prevent brute force attacks
72	  const authRouter = createAuthRoutes(container);
73	  if (authLimiter) {
74	    app.use('/api/auth', authLimiter, authRouter);
75	  } else {
76	    app.use('/api/auth', authRouter);
77	  }
78	
79	  // ============================================================
80	  // USER ROUTES (players, coaches, admins)
81	  // ============================================================
82	  // Apply rate limiting to registration and login endpoints
83	  
84	  // Player routes
85	  const playerRouter = createPlayerRoutes(container);
86	  if (authLimiter) {
87	    // Create a separate router for rate-limited endpoints
88	    const playerAuthRouter = express.Router();
89	    playerAuthRouter.post('/register', authLimiter);
90	    playerAuthRouter.post('/login', authLimiter);
91	    app.use('/api/players', playerAuthRouter);
92	  }
93	  app.use('/api/players', playerRouter);
94	
95	  // Coach routes
96	  const coachRouter = createCoachRoutes(container);
97	  if (authLimiter) {
98	    const coachAuthRouter = express.Router();
99	    coachAuthRouter.post('/register', authLimiter);
100	    coachAuthRouter.post('/login', authLimiter);
101	    app.use('/api/coaches', coachAuthRouter);
102	  }
103	  app.use('/api/coaches', coachRouter);
104	
105	  // Admin routes
106	  const adminRouter = createAdminRoutes(container);
107	  if (authLimiter) {
108	    const adminAuthRouter = express.Router();
109	    adminAuthRouter.post('/register', authLimiter);
110	    adminAuthRouter.post('/login', authLimiter);
111	    app.use('/api/admin', adminAuthRouter);
112	  }
